-- Only the upgrade of existing accounts uses the shipped prefixes.
-- All newly-created master codes are generated by PartyService from appsettings.
INSERT INTO ctracking."partyReferences" ("uniqueId", "userType", "uniqueCode")
SELECT "userId", "userType",
    CASE "userType" WHEN 1 THEN 'EMP-' WHEN 2 THEN 'CON-' ELSE 'SHP-' END ||
    lpad((row_number() OVER (PARTITION BY "userType" ORDER BY "userId"))::text,
         greatest(6, length((row_number() OVER (PARTITION BY "userType" ORDER BY "userId"))::text)), '0')
FROM ctracking."applicationUsers";

INSERT INTO ctracking."Employees"
    ("employeeId", "userType", "uniqueCode", "name", "firstName", "lastName", "dob", "emailId", "version", "createOn", "createdBy", "updatedOn", "updatedBy")
SELECT u."userId", u."userType", r."uniqueCode", btrim(concat_ws(' ', u."firstName", u."lastName")),
    u."firstName", u."lastName", u."dob", u."emailId", 1, u."createOn", u."createdBy", u."updatedOn", u."updatedBy"
FROM ctracking."applicationUsers" u JOIN ctracking."partyReferences" r ON r."uniqueId" = u."userId"
WHERE u."userType" = 1;

INSERT INTO ctracking."Consignees"
    ("consigneeId", "userType", "uniqueCode", "name", "contactName", "emailId", "version", "createOn", "createdBy", "updatedOn", "updatedBy")
SELECT u."userId", u."userType", r."uniqueCode", btrim(concat_ws(' ', u."firstName", u."lastName")),
    left(btrim(concat_ws(' ', u."firstName", u."lastName")), 300), u."emailId", 1, u."createOn", u."createdBy", u."updatedOn", u."updatedBy"
FROM ctracking."applicationUsers" u JOIN ctracking."partyReferences" r ON r."uniqueId" = u."userId"
WHERE u."userType" = 2;

INSERT INTO ctracking."Shippers"
    ("shipperId", "userType", "uniqueCode", "name", "contactName", "emailId", "version", "createOn", "createdBy", "updatedOn", "updatedBy")
SELECT u."userId", u."userType", r."uniqueCode", btrim(concat_ws(' ', u."firstName", u."lastName")),
    left(btrim(concat_ws(' ', u."firstName", u."lastName")), 300), u."emailId", 1, u."createOn", u."createdBy", u."updatedOn", u."updatedBy"
FROM ctracking."applicationUsers" u JOIN ctracking."partyReferences" r ON r."uniqueId" = u."userId"
WHERE u."userType" = 3;

UPDATE ctracking."applicationUsers" u SET "uniqueId" = r."uniqueId", "uniqueCode" = r."uniqueCode"
FROM ctracking."partyReferences" r WHERE r."uniqueId" = u."userId";

UPDATE ctracking."uniqueCodeCounters" c SET "lastNumber" =
    (SELECT count(*) FROM ctracking."partyReferences" r WHERE r."userType" = c."userType");

DO $sequence$
BEGIN
    PERFORM setval(pg_get_serial_sequence('ctracking."partyReferences"', 'uniqueId'),
        greatest(coalesce((SELECT max("uniqueId") FROM ctracking."partyReferences"), 0), 1),
        EXISTS(SELECT 1 FROM ctracking."partyReferences"));
END $sequence$;
